static void render()
{
    auto t1 = std::chrono::steady_clock::now();

    auto deltaTime = std::chrono::duration_cast<std::chrono::microseconds>(t1 - t0).count();
    avg += (1000000.0 / deltaTime);
    total++;

    if (total >= 60) {
        avg /= 60.0;

        printf("%.2f FPS\n", avg);

        avg = 0.0f;
        total = 0;
    }

    t0 = t1;

    SDL_LockTexture(buffer,
        NULL,
        (void**)&pixels,
        &pitch);

    memcpy(pixels, emulator.Screen, SCREEN_WIDTH * 240 * sizeof(int));

    SDL_UnlockTexture(buffer);
    SDL_RenderCopy(renderer, buffer, NULL, NULL);
    SDL_RenderPresent(renderer);
}

static void audio(void* userdata, Uint8* stream, int len)
{
    for (int i = 0; i < len / 2; i++)
    {
        while (t < samplet)
        {
            emulator._CoreCycleAdvance();
            if (emulator.FrameAdvance_ReachedVBlank)
            {
                render();
                emulator.FrameAdvance_ReachedVBlank = false;
			}
            t += clockt;
		}
		t -= samplet;

        double sample = emulator.APU_DMC_Output / 255.0 * 32767.0;
        // Write the sample to the audio buffer (16-bit signed)
        ((Sint16*)stream)[i] = (Sint16)sample;
    }
};

int main(int argc, char* argv[])
{
    if (argc < 2)
    {
        std::cout << "USAGE: TriCNES-cpp.exe nes|fds <...args>" << std::endl;
        return 0;
    }

    if (argv[1][0] == 'n')
    {
        if (argc < 3)
        {
            std::cout << "USAGE: TriCNES-cpp.exe nes rom.nes <tas.r08>" << std::endl;
            return 0;
        }

        TriCNES::Cartridge cartridge(argv[2]);
        emulator.Cart = &cartridge;
        cartridge.Emu = &emulator;

        if (argc == 4) {
            initR08(argv[3]);
        }
    }
    else if (argv[1][0] == 'f')
    {
        if (argc < 4)
        {
            std::cout << "USAGE: TriCNES-cpp.exe fds rom.fds bios.rom" << std::endl;
            return 0;
        }

        TriCNES::Cartridge cartridge(argv[2], argv[3]);
        emulator.Cart = &cartridge;
        cartridge.Emu = &emulator;
    }
    else
    {
        std::cout << "No mode specified, exiting..." << std::endl;

        return 0;
    }

    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO) < 0)
    {
        std::cout << "SDL could not be initialized!" << std::endl
            << "SDL_Error: " << SDL_GetError() << std::endl;
        return 0;
    }

#if defined linux && SDL_VERSION_ATLEAST(2, 0, 8)
    // Disable compositor bypass
    if (!SDL_SetHint(SDL_HINT_VIDEO_X11_NET_WM_BYPASS_COMPOSITOR, "0"))
    {
        std::cout << "SDL can not disable compositor bypass!" << std::endl;
        return 0;
    }
#endif

    SDL_Window* window = SDL_CreateWindow("TriCNES C++",
        SDL_WINDOWPOS_UNDEFINED,
        SDL_WINDOWPOS_UNDEFINED,
        SCREEN_WIDTH, SCREEN_HEIGHT,
        SDL_WINDOW_SHOWN);
    if (!window)
    {
        std::cout << "Window could not be created!" << std::endl
            << "SDL_Error: " << SDL_GetError() << std::endl;
    }
    else
    {
        // Create renderer
        renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
        if (!renderer)
        {
            std::cout << "Renderer could not be created!" << std::endl
                << "SDL_Error: " << SDL_GetError() << std::endl;
        }
        else
        {
            SDL_AudioSpec req;
            SDL_AudioSpec res;

            SDL_zero(req);
            SDL_zero(res);

            req.freq = 44100;
            req.format = AUDIO_S16LSB;
            req.channels = 1;
            req.samples = 128;
            req.callback = audio;

            SDL_AudioDeviceID dev = SDL_OpenAudioDevice(NULL, 0, &req, &res, 0);

            if (dev == 0)
            {
                std::cout << "SDL_OpenAudio failed: " << SDL_GetError() << std::endl;
			}
            else
            {
                printf("----------------\n");
                printf("sample rate:%d\n", res.freq);
                printf("channels:%d\n", res.channels);
                printf("samples:%d\n", res.samples);
                printf("size:%d\n", res.size);
                printf("----------------\n");
                if (res.freq != req.freq ||
                    res.format != req.format ||
                    res.channels != req.channels)
                {
                    std::cout << "Couldn't get desired AudioSpec" << std::endl;
				}
                else
                {
					SDL_PauseAudioDevice(dev, 0);
                }
            }

            buffer = SDL_CreateTexture(renderer,
                SDL_PIXELFORMAT_ARGB8888,
                SDL_TEXTUREACCESS_STREAMING,
                SCREEN_WIDTH,
                240);

            bool quit = false;


            while (!quit)
            {
                SDL_Event e;

                while (SDL_PollEvent(&e)) {
                    if (e.type == SDL_QUIT)
                    {
                        quit = true;
                    }
                    else if (e.type == SDL_KEYDOWN)
                    {
                        switch (e.key.keysym.sym)
                        {
                        case SDLK_x:
                            emulator.ControllerPort1 |= 0x80;
                            break;
                        case SDLK_z:
                            emulator.ControllerPort1 |= 0x40;
                            break;
                        case SDLK_RSHIFT:
                            emulator.ControllerPort1 |= 0x20;
                            break;
                        case SDLK_RETURN:
                            emulator.ControllerPort1 |= 0x10;
                            break;
                        case SDLK_UP:
                            emulator.ControllerPort1 |= 0x08;
                            break;
                        case SDLK_DOWN:
                            emulator.ControllerPort1 |= 0x04;
                            break;
                        case SDLK_LEFT:
                            emulator.ControllerPort1 |= 0x02;
                            break;
                        case SDLK_RIGHT:
                            emulator.ControllerPort1 |= 0x01;
                            break;
                        }
                    }
                    else if (e.type == SDL_KEYUP)
                    {
                        switch (e.key.keysym.sym)
                        {
                        case SDLK_x:
                            emulator.ControllerPort1 &= ~0x80;
                            break;
                        case SDLK_z:
                            emulator.ControllerPort1 &= ~0x40;
                            break;
                        case SDLK_RSHIFT:
                            emulator.ControllerPort1 &= ~0x20;
                            break;
                        case SDLK_RETURN:
                            emulator.ControllerPort1 &= ~0x10;
                            break;
                        case SDLK_UP:
                            emulator.ControllerPort1 &= ~0x08;
                            break;
                        case SDLK_DOWN:
                            emulator.ControllerPort1 &= ~0x04;
                            break;
                        case SDLK_LEFT:
                            emulator.ControllerPort1 &= ~0x02;
                            break;
                        case SDLK_RIGHT:
                            emulator.ControllerPort1 &= ~0x01;
                            break;
                        }
                    }
                }
            }

            SDL_DestroyRenderer(renderer);
        }

        SDL_DestroyWindow(window);
    }

    SDL_Quit();

	return 0;
}
